from __future__ import annotations
from typing import Any, Dict, Optional
from pydantic import BaseModel, Field
from sdk.async_exec_api.modify_order_message_type import ModifyOrderMessageType
from sdk.async_exec_api.modify_order_request import ModifyOrderRequest
class ModifyOrderRequestMessagePayload(BaseModel): 
  type: ModifyOrderMessageType = Field(description='''Message type for modifyOrder request and response''')
  id: str = Field(description='''Client-chosen correlation identifier; must be unique across in-flight requests on the connection.''')
  payload: ModifyOrderRequest = Field(description='''Modifies a resting order in place. The order keeps its `orderId` and `clientOrderId` in all cases. Target exactly one of `orderId` / `clientOrderId`; supplying both or neither is rejected with `INPUT_VALIDATION_ERROR`, and a target that does not resolve to a live resting order is rejected with `ORDER_NOT_FOUND`. The four modifiable fields — `limitPx`, `qty`, `postOnly`, `expiresAfter` — are all required and carry the complete post-modify state of the order; there is no omitted-means-inherited shorthand. The request's EIP-712 signature covers the full post-modify order state, so the client necessarily knows every value; requiring all four keeps the wire contract identical to the signed contract and eliminates sentinel/inherit ambiguity. A request whose post-modify state is identical to the order's current state is rejected with `EMPTY_MODIFY_ERROR`. Non-modifiable attributes (`side`, `timeInForce`, `reduceOnly`, `accountId`, `signerWallet`, `clientOrderId`) always carry over from the resting order. Queue priority: a `qty` decrease at an unchanged `limitPx` preserves the order's place in the book; any `limitPx` change or `qty` increase loses it (re-queued at the new level). `qty` is the TOTAL order quantity, not the remaining quantity, and must be strictly greater than the order's `cumQty` (else `MODIFY_QTY_BELOW_FILLED_ERROR`). If the post-modify order is post-only and would cross, the modification is rejected with `POST_ONLY_WOULD_CROSS_ERROR` and the resting order is left untouched, priority intact. If it is not post-only and the new `limitPx` crosses, the modification executes immediately — the response reports the executed quantity (`execQty`) and resulting `status`, with per-fill detail delivered on the wallet executions and `walletOrderChanges` streams, exactly as for `createOrder`. Requires a fresh EIP-712 signature over the full post-modify order state (the same `Order` envelope as `createOrder`, with the modified values substituted into `OrderDetails` — the signature covers exactly the four values sent plus the inherited immutables) and a fresh `nonce`. See `docs/eip712.md` for the signing algorithm and exact typehash strings.''')
